torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Get dimensions
    // A is (M, K), B is (N, K), we want C = A * B^T which is (M, N)
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(0);

    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    // Create output tensor
    auto C = torch::empty({M, N}, A.options());

    // Create cuBLAS handle
    cublasHandle_t handle;
    cublasCreate(&handle);

    float alpha = 1.0f;
    float beta = 0.0f;

    // cuBLAS uses column-major order, but PyTorch uses row-major. For C = A * B^T, I need to call cublasSgemm with the transposed B parameter and adjust the operation accordingly.

